SELECT V1.NROEMPRESA, V1.CODGERALOPER, V2.SEQPRODUTO, PX.DESCCOMPLETA, SUM(V2.VLRITEM + NVL(V2.VLRICMSST, 0) + NVL(V2.VLRIPI, 0)) AS VALOR FROM MLFV_BASENFE V1 JOIN MFLV_BASEDFITEM V2 ON V2.NROEMPRESA = V1.NROEMPRESA AND V2.SEQNF = V1.SEQNF AND V2.TIPNOTAFISCAL = V1.TIPNOTAFISCAL AND V2.SERIEDF = V1.SERIENF AND V2.NUMERODF = V1.NUMERONF AND V2.SEQPESSOA = V1.SEQPESSOA INNER JOIN MAP_PRODUTO PX ON PX.SEQPRODUTO = V2.SEQPRODUTO WHERE V1.TIPNOTAFISCAL = 'S' AND NVL(V1.STATUSNF, 'A') != 'C' AND V1.DTAEMISSAO >= TO_DATE('01/05/2026', 'DD/MM/YYYY') AND V1.DTAEMISSAO < TO_DATE('02/05/2026', 'DD/MM/YYYY') + 1 AND V2.SEQPRODUTO IN ( SELECT SEQDETALHE2 FROM MBIX_TABCDISTRIB WHERE SEQCONSULTA = (SELECT MAX(SEQCONSULTA) FROM MBI_TABCCONSULTAHIST WHERE CODAPLICACAO = 'MAX1008') AND SEQDETALHE2 NOT IN ( SELECT V2B.SEQPRODUTO FROM MLFV_BASENFE V1B JOIN MFLV_BASEDFITEM V2B ON V2B.NROEMPRESA = V1B.NROEMPRESA AND V2B.SEQNF = V1B.SEQNF AND V2B.TIPNOTAFISCAL = V1B.TIPNOTAFISCAL AND V2B.SERIEDF = V1B.SERIENF AND V2B.NUMERODF = V1B.NUMERONF AND V2B.SEQPESSOA = V1B.SEQPESSOA INNER JOIN MAP_PRODUTO PXB ON PXB.SEQPRODUTO = V2B.SEQPRODUTO LEFT JOIN MAP_FAMFORNEC FPXB ON FPXB.SEQFAMILIA = PXB.SEQFAMILIA AND FPXB.PRINCIPAL = 'S' WHERE V1B.TIPNOTAFISCAL = 'S' AND V1B.CODGERALOPER IN (800, 810, 834, 848) AND NVL(V1B.STATUSNF, 'A') != 'C' AND V1B.DTAEMISSAO >= TO_DATE('01/05/2026', 'DD/MM/YYYY') AND V1B.DTAEMISSAO < TO_DATE('02/05/2026', 'DD/MM/YYYY') + 1 AND FPXB.SEQFORNECEDOR = 16491 ) ) GROUP BY V1.NROEMPRESA, V1.CODGERALOPER, V2.SEQPRODUTO, PX.DESCCOMPLETA
